-- Version = *

create proc CFLYTarget.sBuildingCreate
(
	@ActorId int ,
	@Gid varchar(32) ,
	@NetworkId int,

	@JsonCoordinates nvarchar(max),
	@Coordinates nvarchar(max),

	@AgeClass tinyint,
	@Conso float,
	@Area float,
	@MainPurpose char,
	@MainPurposeDistribution tinyint,
	@SecondaryPurpose char,
	@SecondaryPurposeDistribution tinyint,
	@Energy tinyint,
	@EnergyPercentage tinyint,
	@Energy2 tinyint,
	@Energy2Percentage tinyint,
	@OverwriteIfExists bit = 0
)
as
begin
	--[beginsp]

		declare @g geography;
		set @g = geography::STGeomFromText(@Coordinates, 4326); 
		set @g = case 
			when @g.STIsValid() = 0 then
				case 
					when @g.MakeValid().EnvelopeAngle() > 90 then @g.MakeValid().ReorientObject() 
					else @g.MakeValid()  
				end
			else
				case 
					when @g.EnvelopeAngle() > 90 then @g.ReorientObject() 
					else @g 
				end
		end


		merge CFLYTarget.tBuilding as target
		using ( select Gid = @Gid, NetworkId = @NetworkId ) as source 
		on ( source.Gid = target.Gid and source.NetworkId = target.NetworkId )
		when not matched 
			by target then 
				insert ( Gid, JsonCoordinates, Coordinates, NetworkId, ValidationDate, AgeClass, Conso, Area, MainPurpose, MainPurposeDistribution, SecondaryPurpose, SecondaryPurposeDistribution, Energy, EnergyPercentage, Energy2, Energy2Percentage ) 
				values ( @Gid, @JsonCoordinates, @g, @NetworkId, '', @AgeClass, @Conso, @Area, @MainPurpose, @MainPurposeDistribution, @SecondaryPurpose, @SecondaryPurposeDistribution, @Energy, @EnergyPercentage, @Energy2, @Energy2Percentage )
		when matched and @OverwriteIfExists = 1 then 
				update 
					set 
						Coordinates = @g,
						JsonCoordinates = @JsonCoordinates,
						Conso = @Conso,
						AgeClass = @AgeClass,
						Area = @Area,
						MainPurpose = @MainPurpose,
						MainPurposeDistribution = @MainPurposeDistribution,
						SecondaryPurpose = @SecondaryPurpose,
						SecondaryPurposeDistribution = @SecondaryPurposeDistribution,
						Energy = @Energy,
						EnergyPercentage = @EnergyPercentage,
						Energy2 = @Energy2,
						Energy2Percentage = @Energy2Percentage,
						SharedData = '{"conso":'+cast(IsNull(Conso,0) as varchar(30))+',"area":'+cast(IsNull(Area,0) as varchar(30))+',"mainPurpose":"'+cast(IsNull(MainPurpose,'') as varchar(30))+'","mainPurposeDistribution":'+cast(IsNull(MainPurposeDistribution, '') as varchar(30))+',"secondaryPurpose":"'+cast(IsNull(SecondaryPurpose, '') as varchar(30))+'","secondaryPurposeDistribution":'+cast(IsNull(SecondaryPurposeDistribution,'') as varchar(30))+',"energy":'+cast(IsNull(Energy,'') as varchar(30))+',"energy2":'+cast(IsNull(Energy2,'') as varchar(30))+',"energyPercentage":'+cast(IsNull(EnergyPercentage,'') as varchar(30))+',"energy2Percentage":'+cast(IsNull(Energy2Percentage,'') as varchar(30))+',"ageClass":'+case when AgeClass is null then '-1' else cast( AgeClass as varchar(30) ) end +'}'
		;

	--[endsp]
end

        create procedure CKCore.sErrorRethrow
        (
	        @ProcId int
        )
        as
        begin
	        declare @EM nvarchar(2048) = ERROR_MESSAGE();

	        if @EM is not null
	        begin
		        declare @ON sysname;
		        if @EM like 'ck:%-{%}-[[]%]%' 
		        begin
			        set @ON = OBJECT_NAME(@ProcId);
			        if @ON is null set @ON = N'(dynamic)';
			        else set @ON = OBJECT_SCHEMA_NAME(@ProcId)+'.'+@ON;
			        set @EM = @EM+'<-'+@ON;
			        raiserror( @EM, 16, 1 );
		        end
		        else
		        begin
			        set @ON = ERROR_PROCEDURE();
			        if @ON is null set @ON = N'(dynamic)';
			        declare @LN int = ERROR_LINE();
			        raiserror( N'ck:%s-{%d}-[%s]', 16, 1, @ON, @LN, @EM );
		        end			
	        end
        end

        create procedure CK.sResDataStringSet -- Merge inside!
        (
	        @ResId int, 
	        @Val nvarchar(400)
        )
        as begin
	        set nocount on;
	        merge CK.tResDataString as t 
		        using (select ResId = @ResId, Val = @Val) as s
		        on t.ResId = s.ResId
		        when matched then update set Val = @Val
		        when not matched then insert(ResId,Val) values (@ResId, @Val);
	        return 0;
        end

create procedure CK.sGroupRemoveAllUsers
(
    @ActorId int,
    @GroupId int
)
as begin
  if @ActorId <= 0 raiserror( 'Security.AnonymousNotAllowed', 16, 1 );
  if @GroupId <= 0 raiserror( 'Group.InvalidGroup', 16, 1 );

  --[beginsp]

  declare @UserId int;
  declare @CUser cursor;
  set @CUser = cursor local fast_forward for
          select ActorId from CK.tActorProfile where GroupId = @GroupId and ActorId <> @GroupId;
  open @CUser;

  fetch from @CUser into @UserId;
  while @@FETCH_STATUS = 0
  begin
    exec CK.sGroupUserRemove @ActorId, @GroupId, @UserId;
    fetch next from @CUser into @UserId;
  end
  deallocate @CUser;

  --[endsp]
end
